#requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory)][string]$Plan,[string]$PgBin='C:\Program Files\PostgreSQL\19\bin')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Read-Hidden([string]$Label){$s=Read-Host -Prompt $Label -AsSecureString;try{if($s.Length-eq 0){throw 'Value cannot be empty.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Send([Net.Http.HttpMethod]$Method,[string]$Path,[object]$Payload,[switch]$Rpc){$q=[Net.Http.HttpRequestMessage]::new($Method,$Path);try{if($Rpc){$q.Headers.Add('Content-Profile','reivro_checks_api')};$j=ConvertTo-Json $Payload -Depth 20 -Compress;$q.Content=[Net.Http.StringContent]::new($j,[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function Invoke-PsqlJson([string]$Sql,[guid]$WorkerId){$op=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$or=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$cn='host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full';$o=& $script:psql '-X' '-w' '-qAt' '-v' 'ON_ERROR_STOP=1' '-d' $cn '-v' "repository_id=$($script:f.repository_id)" '-v' "contract_id=$($script:f.contract_id)" '-v' "submission_id=$($script:f.submission_id)" '-v' "agent_id=$($script:f.agent_id)" '-v' "digest=$($script:f.digest)" '-v' "base_sha=$($script:f.base_sha)" '-v' "head_sha=$($script:f.head_sha)" '-v' "worker_id=$WorkerId" '-f' $Sql;if($LASTEXITCODE-ne 0){throw "psql exited $LASTEXITCODE"};$line=@($o|Where-Object{$_-match'^\{'})[-1];$line|ConvertFrom-Json}finally{if($null-eq$op){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$op};if($null-eq$or){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$or}}}
$client=$handler=$key=$email=$password=$session=$dbPassword=$null;$stage='plan';$writeAttempted=$false;$rpcFailure=$null
try{
 $pre=Join-Path $PSScriptRoot 'preflight_staging_first_claim.sql';$post=Join-Path $PSScriptRoot 'postcheck_staging_first_claim.sql';$cert=Join-Path $HOME 'Downloads\prod-ca-2021.crt'
 foreach($p in $Plan,$pre,$post,$cert){if(-not(Test-Path -LiteralPath $p)){throw "Required path missing: $p"}}
 $f=Get-Content -LiteralPath $Plan -Raw|ConvertFrom-Json
 if($f.staging_ref-cne'lbklqqqbmeyseeccdqog'-or [guid]$f.agent_id-ne[guid]'0dae2b29-adaa-48b6-9a96-e9ac646b2a7a'-or [guid]$f.contract_id-eq[guid]::Empty-or [guid]$f.submission_id-eq[guid]::Empty-or [long]$f.repository_id-le 0-or [string]$f.base_sha-cne'07fc0b907d3aa9659ea7541f80acf6c18586e645'-or [string]$f.head_sha-cne'e0d50dd239f8c8c3c39df84187741009f7496d09'-or [string]$f.digest-cnotmatch'^[0-9a-f]{64}$'){throw 'Private plan differs from approved fixture.'}
 $psql=(Get-Command(Join-Path $PgBin 'psql.exe')-CommandType Application).Source;if((&$psql --version)-notmatch'\s19\.\d+(?:\s|$)'){throw 'Use PostgreSQL 19 psql.'};$ca=(Resolve-Path -LiteralPath $cert).Path
 $key=(Read-Hidden 'Staging default publishable key').Trim();$email=(Read-Hidden 'Worker A staging email').Trim();$password=Read-Hidden 'Worker A staging password';$dbPassword=Read-Hidden 'Staging PostgreSQL password for reconciliation';if($key-cnotmatch'^sb_publishable_[A-Za-z0-9_-]+$'){throw 'Invalid publishable key.'}
 $stage='preflight';$scope=Invoke-PsqlJson $pre ([guid]::Empty);$workerId=[guid]$scope.worker_id;if($workerId-eq[guid]::Empty-or[long]$scope.installation_id-le 0-or[string]::IsNullOrWhiteSpace([string]$scope.repository)-or[string]::IsNullOrWhiteSpace([string]$scope.base_ref)){throw 'Execution scope preflight failed.'};Write-Output 'PASS claim scope and submission preflight'
 Add-Type -AssemblyName System.Net.Http;[Net.ServicePointManager]::SecurityProtocol=[Net.ServicePointManager]::SecurityProtocol-bor[Net.SecurityProtocolType]::Tls12;$handler=[Net.Http.HttpClientHandler]::new();$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.Timeout=[TimeSpan]::FromSeconds(15);$client.DefaultRequestHeaders.Add('apikey',$key);$key=$null
 $stage='worker login';$x=Send ([Net.Http.HttpMethod]::Post) '/auth/v1/token?grant_type=password' @{email=$email;password=$password};if($x.Status-lt 200-or$x.Status-ge 300){throw "Login HTTP $($x.Status)"};$session=$x.Body|ConvertFrom-Json;if($session.user.id-cne$workerId.ToString()){throw 'Unexpected Worker identity.'};$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$session.access_token);$email=$password=$session=$null;Write-Output 'PASS Worker A Auth identity'
 $stage='authorization';$approval=Read-Host 'Type STAGING-FIRST-WORKER-CLAIM-APPROVED to execute the authorized claim';if($approval-cne'STAGING-FIRST-WORKER-CLAIM-APPROVED'){throw 'Worker claim not confirmed.'}
 $request=@{repository_id=[long]$f.repository_id;installation_id=[long]$scope.installation_id;repository=[string]$scope.repository;base_ref=[string]$scope.base_ref;id=[string]$f.submission_id;delivery=[string]$f.submission_id;pr=1;base_sha=[string]$f.base_sha;head_sha=[string]$f.head_sha;digest=[string]$f.digest;verifier='task-completion-v1'}
 $stage='claim';$writeAttempted=$true;try{$x=Send ([Net.Http.HttpMethod]::Post) '/rest/v1/rpc/task_dispatch' @{action='claim';request=$request} -Rpc;if($x.Status-lt 200-or$x.Status-ge 300){throw "Claim HTTP $($x.Status)"};$claim=$x.Body|ConvertFrom-Json;if($claim.state-cne'running'-or[guid]$claim.run_id-eq[guid]::Empty-or[guid]$claim.attempt_id-eq[guid]::Empty-or[int]$claim.fence-ne 1-or$claim.digest-cne[string]$f.digest-or$claim.base_sha-cne[string]$f.base_sha-or$claim.head_sha-cne[string]$f.head_sha-or$claim.verifier-cne'task-completion-v1'){throw 'Unexpected claim receipt.'}}catch{$rpcFailure=$_}
 $stage='postcheck';$saved=Invoke-PsqlJson $post $workerId;if(-not[bool]$saved.all_checks_pass){throw 'Persisted claim state failed reconciliation.'};if($null-ne$rpcFailure){Write-Output 'PASS claim reconciled after uncertain RPC response'}elseif([guid]$saved.run_id-ne[guid]$claim.run_id-or[guid]$saved.attempt_id-ne[guid]$claim.attempt_id-or[int]$saved.fence-ne[int]$claim.fence){throw 'Claim response and persisted lease differ.'}
 Write-Output 'PASS run lease fence and execution scope reconciled';Write-Output 'FIRST_WORKER_CLAIM_RUNNING_NO_EXECUTION_RESULT'
}catch{[Console]::Error.WriteLine("FAIL $stage");if($writeAttempted){[Console]::Error.WriteLine('Do not retry. Reconcile the submission and lease first.')};exit 1}finally{$key=$email=$password=$session=$dbPassword=$approval=$claim=$x=$null;Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.DefaultRequestHeaders.Authorization=$null;$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
